import sys, json, platform, unicodedata, stringprep
from encodings.idna import nameprep
from pathlib import Path
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
root = Path('/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime')
tables = json.loads((root / '__snapshots__/stringprep-3.14.7.json').read_text())
points = {0, 0x10ffff}
for point, _ in tables['boundaryCases']:
    points.add(point)
for point, _ in tables['mappings']['b2']:
    points.update(p for p in (point-1, point, point+1) if 0 <= p <= 0x10ffff)
inputs = [[p] for p in sorted(points)]
strings = ['', 'ABC', 'Straße', 'İ', 'Å\u0323', 'A\u030a', '\u00ad\u034f\u1806\u200b', 'א', 'א1ב', 'אaב', '1אב', 'אב1', 'א\x00a', '\x00א', 'א\x00', '\u1e9e', '\U0001f600', '\ud800\udc00', 'A\u202eB', '①Ａ㍿', '\U0002f868']
inputs += [[ord(c) for c in s] for s in strings]
alphabet = [0, 9, 10, 32, 65, 66, 97, 0xad, 0xdf, 0x130, 0x300, 0x301, 0x315, 0x323, 0x345, 0x34f, 0x3a3, 0x3c2, 0x5d0, 0x5d1, 0x627, 0x661, 0x1680, 0x1806, 0x1e9e, 0x200b, 0x202e, 0x212b, 0x2163, 0x3000, 0xac00, 0xd800, 0xdc00, 0xff21, 0x1f600, 0x2f868, 0x10ffff]
seed = 0x3491
for index in range(1024):
    row = []
    for _ in range(index % 13):
        seed = (1664525 * seed + 1013904223) & 0xffffffff
        row.append(alphabet[seed % len(alphabet)])
    inputs.append(row)
rows = []
for points in inputs:
    source = ''.join(map(chr, points))
    try:
        outcome = {'result': list(map(ord, nameprep(source)))}
    except UnicodeEncodeError as error:
        outcome = {'error': {'name': type(error).__name__, 'encoding': error.encoding, 'object': list(map(ord, error.object)), 'start': error.start, 'end': error.end, 'reason': error.reason, 'message': str(error)}}
    rows.append({'input': points, **outcome})
result = {'oracle': {'executable': sys.executable, 'version': sys.version, 'platform': platform.platform(), 'unicode': unicodedata.unidata_version, 'normalization': unicodedata.ucd_3_2_0.unidata_version, 'source': Path(__file__).read_text(), 'exitStatus': 0, 'stderr': '', 'signal': None}, 'cases': rows}
(root / '__snapshots__/idna-nameprep-3.14.7.json').write_text(json.dumps(result, ensure_ascii=True, separators=(',', ':')) + '\n')
print(len(rows))
